   "orig": "Rising emissions and temperatures: The cost of Trump's climate retreat is now clear",
   "lead": "Il mondo si avvia a superare la soglia critica di riscaldamento globale di 1,5 gradi, e la decisione del presidente statunitense Donald Trump di ritirare gli Stati Uniti dagli impegni internazionali sul clima peggiora ulteriormente il quadro. Lo evidenzia un nuovo rapporto delle Nazioni Unite, che sottolinea l'aumento dei costi ambientali derivanti dalla retromarcia climatica di Washington. Lo riferisce Deutsche Welle.",
