    "Gli accordi internazionali sul clima mirano a limitare l'aumento della temperatura globale media al di sotto di 1,5 gradi rispetto ai livelli pre-industriali, al fine di evitare gli impatti più catastrofici dei mutamenti climatici sul pianeta."
