   "titolo": "Regno Unito: via libera al giacimento di gas nel Mare del Nord, tensioni con i deputati laburisti e gli attivisti",
   "orig": "Andy Burnham faces climate revolt after approval of North Sea gas drilling",
   "lead": "Il governo britannico ha annunciato l'approvazione del discusso progetto estrattivo per il giacimento di gas Jackdaw nel Mare del Nord. La decisione, sostenuta da Andy Burnham e formalizzata dai ministri dell'Energia Miatta Fahnbulleh e delle Finanze John Healey ad Aberdeen, ribadisce l'impegno del Regno Unito verso l'industria dei combustibili fossili, scatenando immediate proteste da parte dei deputati laburisti e degli attivisti climatici per il compromesso sulle credenziali verdi. Lo riferisce The Guardian.",
   "more": [
    "Lo sfruttamento dei giacimenti di idrocarburi nel Mare del Nord rappresenta una questione economica e geopolitica centrale per il Regno Unito, diviso tra la necessità di garantire la sicurezza energetica nazionale e gli impegni di decarbonizzazione."
   ],
