   "titolo": "Carín León, la superstar della musica messicana tra successo e romanticismo",
   "orig": "Carín León looks every bit the macho Mexican superstar. But beneath is a romantic",
   "lead": "Fresco di una residenza di sei serate presso la Sphere di Las Vegas, il cantante Carín León si conferma come una delle figure di punta del panorama musicale messicano. Dietro l'immagine da duro, l'artista mostra una vena profondamente romantica, capace di interpretare sentimenti universali attraverso la sua musica. Lo riferisce NPR – Musica.",
   "more": [
    "La musica regionale messicana e i generi correlati riscuotono un enorme successo commerciale non solo in America Latina ma anche negli Stati Uniti, riempiendo arene di grande prestigio internazionale."
   ],
