    "Il processo di certificazione dei nuovi modelli aeronautici da parte delle autorità federali americane è diventato particolarmente rigoroso in seguito agli incidenti e ai controlli straordinari sulla sicurezza che hanno coinvolto la gamma 737 Max negli ultimi anni."
