   "orig": "Penguins' Ben Kindel stable at Utah hospital after medical emergency on team flight",
   "lead": "L'attaccante dei Pittsburgh Penguins Ben Kindel è stato ricoverato in condizioni stabili in un ospedale di Salt Lake City in seguito a un'emergenza medica improvvisa insorta a bordo dell'aereo della squadra, mentre il club faceva ritorno da una trasferta di quattro partite. Lo riferisce CBC News.",
