   "sez": "tech",
   "titolo": "Il primo ministro malese Anwar mette in guardia contro l'app Waze per problemi di sicurezza dei dati",
   "orig": "Malaysia PM Anwar warns against Israeli navigation app Waze over data security concerns",
   "lead": "A causa dei timori legati all'utilizzo dell'applicazione per monitorare i dati dei cittadini malesi, il primo ministro della Malaysia Anwar ha suggerito alla popolazione di passare a Tuju, un servizio sviluppato dall'Autorità autostradale malese. Lo riferisce CNA.",
   "more": [
    "Le applicazioni di navigazione stradale raccolgono e elaborano costantemente una grande quantità di dati relativi agli spostamenti degli utenti, come la posizione geografica in tempo reale e le abitudini di viaggio. Questa mole di informazioni sensibili solleva spesso questioni cruciali legate alla sicurezza informatica e alla protezione della privacy, spingendo in alcuni casi le autorità nazionali a promuovere soluzioni tecnologiche interne o alternative ritenute più sicure e sotto il diretto controllo statale."
   ],
