   "sez": "italia",
   "titolo": "I giovani delle periferie di Milano raccontano noia e povertà",
   "orig": "REPORTAGE I ragazzi della periferia di Milano: 'Qui solo noia e povertà'",
   "lead": "Un reportage dedicato ai ragazzi delle periferie di Milano fotografa una realtà segnata da un forte senso di isolamento, dove i giovani lamentano la mancanza di opportunità e descrivono la loro quotidianità tra noia e povertà economica. Tra i punti di riferimento viene citato il rapper Marracash per la sua forte capacità di attrarre un pubblico affezionato, mentre un esperto evidenzia il disagio di chi avverte una netta sensazione di esclusione sociale rispetto al resto della città. Lo riferisce ANSA.",
   "more": [
    "Le periferie delle grandi aree metropolitane affrontano spesso complesse sfide sociali ed economiche, caratterizzate da una carenza di spazi di aggregazione giovanile e da minori opportunità formative e lavorative. In questi contesti, la musica e in particolare la cultura hip-hop rappresentano frequentemente un canale fondamentale di espressione e di riscatto, offrendo una voce a chi sperimenta forme di marginalità e alienazione urbana."
   ],
