   "id": "z7937da21",
   "sez": "ingegneria",
   "titolo": "Forbo Flooring punta sulle potenzialità creative dei pavimenti personalizzati",
   "orig": "Forbo Flooring spotlights creative possibilities of custom flooring",
   "lead": "L'azienda specializzata in pavimentazioni Forbo Flooring Systems promuove le ampie possibilità di design personalizzato per rendere i pavimenti una parte integrante dell'identità e della storia di uno spazio. Sfruttando tecniche di personalizzazione che spaziano dalla stampa digitale di motivi floreali e grafici fino a immagini fotografiche e intarsi di precisione, il marchio applica queste soluzioni alle sue collezioni tra cui Flotex, Vinyl, Entrance Flooring e Marmoleum. Lo riferisce Dezeen.",
   "more": [
    "Nel settore dell'architettura d'interni e dell'ingegneria dei materiali, la personalizzazione delle superfici calpestabili consente di andare oltre la semplice funzione pratica del pavimento. L'impiego di tecnologie avanzate di stampa digitale e di taglio di precisione permette di trasformare gli elementi strutturali in veri e propri componenti narrativi ed estetici, capaci di riflettere l'identità visiva e il carattere distintivo di un ambiente commerciale o residenziale."
   ],
