   "sez": "salute",
   "titolo": "I consigli alimentari del cardiologo per contrastare il colesterolo alto",
   "orig": "Dieta per il colesterolo alto: cosa mangiare",
   "lead": "Un'alimentazione corretta ed equilibrata gioca un ruolo cruciale nella lotta contro l'ipercolesterolemia e nella salvaguardia della salute cardiovascolare. Per affrontare il problema e proteggere il cuore, il cardiologo Marco Toselli fornisce indicazioni specifiche su quali cibi inserire nella propria dieta quotidiana. Lo riferisce La Cucina Italiana.",
   "more": [
    "L'ipercolesterolemia, ovvero la presenza di livelli elevati di colesterolo nel sangue, rappresenta uno dei principali fattori di rischio per l'insorgenza di malattie cardiovascolari come infarti e ictus. Una dieta ricca di fibre, verdure, legumi e grassi sani, unita alla riduzione dei grassi saturi e trans, contribuisce in modo significativo a mantenere i parametri lipidici entro i limiti di sicurezza, riducendo l'impatto delle patologie cardiache sulla popolazione."
   ],
