   "sez": "italia",
   "titolo": "Aggiornamenti sui concorsi PNRR e sulle immissioni in ruolo nella newsletter del 23 ottobre",
   "orig": "Le graduatorie aggiornate dei concorsi PNRR, gli elenchi regionali, le assunzioni da GPS nella newsletter di venerdì 23 ottobre",
   "lead": "Con la conclusione delle procedure di immissione in ruolo per l'anno scolastico 2026/27, l'attenzione del mondo scolastico si sposta verso il futuro, guardando già all'estate del 2027. La newsletter in uscita venerdì 23 ottobre analizzerà diversi temi chiave, tra cui l'arrivo di un nuovo concorso, lo stato delle graduatorie ancora aperte relative ai bandi del 2018, del 2020 e del PNRR, la ricostituzione degli elenchi regionali e le prospettive legate al doppio canale di assunzione che include le GPS. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il sistema di reclutamento del personale docente in Italia rappresenta uno dei nodi centrali della gestione scolastica pubblica, caratterizzato da complesse procedure concorsuali e da graduatorie a esaurimento o provinciali. La gestione delle supplenze e il passaggio dai contratti a tempo determinato alle assunzioni stabili sono al centro del dibattito istituzionale e sindacale per garantire la copertura regolare dei posti vacanti negli istituti di tutto il Paese."
   ],
