   "titolo": "Iniziativa Atoms4Food dell'Aiea per la protezione della biodiversità",
   "orig": "Atoms4Food: Protecting Biodiversity",
   "lead": "L'Agenzia internazionale per l'energia atomica promuove il programma Atoms4Food, un'iniziativa incentrata sulla tutela della biodiversità e sullo sviluppo di soluzioni scientifiche per la sicurezza alimentare globale. Lo riferisce Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "L'impiego di tecniche nucleari pacifiche, come l'irradiazione per l'induzione di mutazioni genetiche controllate nelle colture, consente agli scienziati di sviluppare varietà vegetali più resistenti alle malattie e ai cambiamenti climatici. Questi metodi scientifici avanzati contribuiscono in modo determinante a preservare le risorse genetiche agricole e a garantire approvvigionamenti alimentari stabili nelle aree del pianeta più vulnerabili."
   ],
