   "lead": "Il lungometraggio d'animazione giapponese ha svelato la partecipazione di tre nuovi doppiatori che andranno a completare il cast vocale della pellicola, la cui uscita nelle sale cinematografiche in Giappone è prevista per l'11 febbraio 2027. Lo riferisce Anime News Network.",
