   "sez": "mondo",
   "titolo": "Nuova allerta aerea e messaggi RO-Alert nella contea romena di Tulcea per possibili droni",
   "orig": "„Posibilă incursiune de drone”. Nouă alertă aeriană și mesaje RO-Alert în Tulcea. Anunțul MApN",
   "lead": "Il sistema di sorveglianza radar del Ministero della Difesa Nazionale della Romania ha rilevato un gruppo di bersagli aerei situato a nord-est della località di Vâlcove, nello spazio aereo ucraino. A seguito del rilevamento, il Centro Nazionale Militare di Comando ha prontamente informato l'Ispettorato Generale per le Situazioni di Emergenza per l'attivazione delle procedure di sicurezza e l'emissione di avvisi alla popolazione tramite il sistema RO-Alert nella zona di Tulcea. Lo riferisce HotNews.",
   "more": [
    "La vicinanza delle regioni di confine romene con i territori ucraini interessati dai conflitti bellici comporta frequenti sconfinamenti o rilevamenti di attività aeree sospette nei pressi dello spazio aereo della Nato. Le autorità locali attivano regolarmente protocolli di protezione civile e allerta preventiva per garantire la sicurezza dei residenti nelle aree prospicienti la zona di crisi."
   ],
