   "sez": "ingegneria",
   "titolo": "Piedra Bay House: l'architettura che dialoga con il paesaggio arido della Repubblica Dominicana",
   "orig": "Piedra Bay House / U-Guide Space Design Atelier",
   "lead": "Progettato dallo studio U-Guide Space Design Atelier a Palmar de Ocoa, nella provincia di Azua nella Repubblica Dominicana, il progetto residenziale Casa Piedra Bay nasce per fondersi con il contesto costiero arido caratterizzato dal contrasto tra le montagne e il Mar dei Caraibi. L'opera ingegneristica e architettonica risponde alle condizioni ambientali attraverso una composizione spaziale che privilegia la ventilazione naturale, il filtraggio della luce solare, la privacy e una connessione costante con il paesaggio circostante. Lo riferisce ArchDaily.",
   "more": [
    "L'architettura bioclimatica applicata ad ambienti costieri e aridi richiede soluzioni progettuali specifiche orientate al comfort termico senza l'ausilio esclusivo di impianti meccanici. L'orientamento strategico degli edifici, l'impiego di schermature solari e la promozione della circolazione naturale dell'aria consentono di mitigare le alte temperature esterne, riducendo l'impatto energetico e valorizzando al contempo le peculiarità geografiche del sito."
   ],
