   "titolo": "Le barriere di sicurezza stradali diventano sedute pubbliche alla Dutch Design Week",
   "orig": "red-and-white aluminum safety barriers convert into public seating at dutch design week",
   "lead": "Durante la Dutch Design Week nei Paesi Bassi, lo studio Martins Mezulis e 13_0663_tsx ha presentato la collezione 'Stop!'. Il progetto reinterpreta le tradizionali barriere di sicurezza in alluminio bianco e rosso, trasformandole in panchine modulari e sgabelli. L'iniziativa punta a convertire elementi restrittivi dell'infrastruttura stradale urbana in spazi accoglienti per la sosta e l'aggregazione dei cittadini. Lo riferisce Designboom.",
   "more": [
    "Il design modulare applicato all'arredo urbano consente di riutilizzare materiali industriali o di cantiere per scopi collettivi. Soluzioni di questo tipo riducono gli sprechi e offrono nuove modalità di fruizione dello spazio pubblico, trasformando oggetti nati per regolare il traffico o delimitare aree in elementi di condivisione."
   ],
