   "sez": "mondo",
   "titolo": "Ingegneri del MIT e dell'EPFL studiano il volo e il nuoto degli uccelli marini",
   "orig": "It’s a bird, it’s a plane … it’s a robo-puffin?",
   "lead": "Gli ingegneri del MIT a Cambridge e dell'EPFL a Losanna in Svizzera stanno studiando la meccanica di volo e nuoto di uccelli marini come i gabbiani e le pulcinelle di mare. Nonostante l'acqua sia mille volte più densa dell'aria, questi animali riescono a immergersi in mare, nuotare sott'acqua e balzare nuovamente in aria per volare. Lo studio analizza le differenze fisiche necessarie per muoversi in questi due diversi ambienti. Lo riferisce MIT Technology Review.",
   "more": [
    "La locomozione trans-mediale, ovvero la capacità di muoversi agevolmente sia in aria sia in acqua, rappresenta una sfida complessa per la robotica. Lo studio della natura aiuta a progettare veicoli autonomi capaci di operare in entrambi i fluidi sfruttando dinamiche simili a quelle biologiche."
   ],
