   "lead": "La Thailandia punta a definire un quadro normativo chiaro per le aziende del settore dei data center entro il primo trimestre del 2027. Secondo quanto dichiarato dal vice ministro dell'Economia digitale e della società Nan Boonthida Somchai, la misura serve a sbloccare importanti piani di investimento nel Paese. Lo riferisce Bangkok Post.",
