   "titolo": "Proteste dei tir in Italia: continuano i blocchi al Sud, revoca in Sicilia",
   "orig": "Proteste Italia, in Campania, Puglia e Calabria ancora blocco tir. Sospeso in Sicilia LIVE",
   "lead": "Nonostante lo sblocco da parte del governo di 480 milioni di euro per l'autotrasporto e l'annuncio di oltre 150 milioni di nuove risorse, la protesta dei camionisti non si ferma. Restano attivi i presidi in diverse regioni del Sud Italia, in particolare in Campania, Puglia e Calabria, in attesa di proposte concrete, mentre in Sicilia la protesta è stata revocata. A causa dei blocchi, si registrano scaffali vuoti nei supermercati soprattutto nelle province di Caserta e Napoli, oltre che in Molise e Lazio, con carenze soprattutto di frutta e verdura. Lo riferisce Sky TG24.",
