   "id": "zb365d172",
   "sez": "dibattito",
   "titolo": "'Progetto di destabilizzazione': quattro maggiorenni restano in carcere mentre la Cgil scende in piazza",
   "orig": "'Progetto di destabilizzazione', quattro maggiorenni restano in carcere",
   "lead": "Quattro maggiorenni restano in carcere nell'ambito di un'indagine su un presunto progetto di destabilizzazione, mentre per i minori coinvolti sono state disposte comunità o domiciliari. Sulla vicenda si inserisce la mobilitazione della Cgil in piazza, accompagnata dalle dichiarazioni del sindaco Sala, secondo cui «non si può solo reprimere». Lo riferisce ANSA.",
   "more": [
    "Il dibattito sulla gestione dell'ordine pubblico e sulle misure restrittive per i giovani coinvolti in episodi di tensione sociale divide istituzioni e sindacati in Italia. Da un lato si invocano interventi di sicurezza e tutela della legalità, dall'altro si sottolinea la necessità di risposte sociali ed educative per prevenire il disagio."
   ],
