   "sez": "mondo",
   "titolo": "Il Giappone fornirà alla Malaysia un sistema antidrone",
   "orig": "Japan to provide Malaysia with counterdrone system",
   "lead": "Il governo giapponese stanzierà 1,65 miliardi di yen per fornire alla Malaysia un sistema di difesa contro i droni. Si tratta della terza operazione di assistenza ufficiale alla sicurezza concessa da Tokyo a favore di Kuala Lumpur. Lo riferisce The Japan Times.",
   "more": [
    "La cooperazione nella sicurezza tra Stati asiatici riveste un ruolo strategico per la stabilità regionale e il contrasto a nuove minacce tecnologiche, come l'impiego non autorizzato di velivoli senza pilota. Il Giappone ha progressivamente ampliato il proprio quadro di aiuti militari all'estero per rafforzare le capacità di difesa dei Paesi partner nell'area indo-pacifica."
   ],
