   "id": "zc6a3a639",
   "sez": "ingegneria",
   "titolo": "Il ponte di Lifford ospita la sperimentazione di un sistema di monitoraggio continuo della corrosione",
   "orig": "Lifford Bridge hosts trial of system offering continuous half-joint corrosion monitoring",
   "lead": "Sul ponte di Lifford, che attraversa il fiume Foyle tra Irlanda e Irlanda del Nord, è in corso la sperimentazione di una nuova tecnologia progettata per monitorare ininterrottamente la corrosione delle strutture in calcestruzzo. Il sistema mira a supportare i tecnici nelle decisioni ingegneristiche quando le infrastrutture si avvicinano alla fine del loro ciclo di vita. Lo riferisce New Civil Engineer.",
   "more": [
    "Il degrado del calcestruzzo e l'ossidazione delle armature metalliche rappresentano problemi critici per la manutenzione delle grandi opere civili come i ponti. L'adozione di sensori per il monitoraggio continuo consente di stimare con maggiore precisione la sicurezza strutturale e pianificare interventi mirati."
   ],
