   "sez": "salute",
   "titolo": "Primo studio clinico sull'uomo per un catetere a doppia imaging per valutare il rischio di infarto",
   "orig": "First-in-human study of dual-imaging catheter to assess heart attack risk, guide treatment",
   "lead": "I ricercatori del Centro nazionale di tecnologie biofotoniche interventistiche dell'Università della California a Davis hanno completato il primo test clinico sull'uomo di un nuovo dispositivo a catetere flessibile. Lo strumento è progettato per muoversi all'interno delle arterie e raccogliere in tempo reale informazioni dettagliate sull'accumulo di placca aterosclerotica, aiutando i medici a diagnosticare e trattare la patologia. Lo riferisce Medical Xpress.",
   "more": [
    "L'aterosclerosi consiste nell'restringimento dei vasi sanguigni causato dall'accumulo di depositi di grasso e placca, una delle principali cause di infarti e patologie cardiovascolari. L'utilizzo di cateteri avanzati dotati di tecnologie di imaging interno permette di analizzare con precisione la composizione delle pareti arteriose."
   ],
