   "lead": "La rivista Engineering News-Record ha pubblicato la rassegna periodica dedicata ai professionisti dell'ingegneria, dell'edilizia e delle costruzioni attiva nella regione degli Stati del sud-ovest e delle Montagne Rocciose per i mesi di ottobre e novembre. Lo riferisce Engineering News-Record.",
