   "id": "z538fdfd7",
   "sez": "mondo",
   "titolo": "I preparativi a Filadelfia in vista del voto per le elezioni",
   "orig": "Inside Philadelphia's preparations for Election Day",
   "lead": "Nella fase finale della campagna elettorale, che vede già oltre dodici milioni di voti espressi a livello nazionale, la città di Filadelfia si prepara alle operazioni di voto per le elezioni. I procedimenti elettorali della città sono stati oggetto di critiche da parte del presidente Trump nell'ultimo decennio, spingendo le autorità locali a rafforzare l'organizzazione logistica in vista dell'appuntamento alle urne. Lo riferisce PBS NewsHour.",
   "more": [
    "L'organizzazione delle elezioni negli Stati Uniti d'America è gestita a livello locale e municipale, rendendo le grandi metropoli snodi cruciali per la verifica dei flussi di voto e la trasparenza dello spoglio durante le consultazioni presidenziali o di midterm."
   ],
