   "sez": "economia",
   "titolo": "Il nodo ferroviario di Stratford si avvicina al potenziamento internazionale grazie ai fondi del bilancio statale",
   "orig": "Stratford moves closer to international rail upgrade with Budget boost",
   "lead": "Il sindaco di Londra, Sadiq Khan, ha condotto una serie di colloqui per definire le opzioni di finanziamento destinate al miglioramento del polo ferroviario di Stratford, traendobeneficio dai nuovi stanziamenti previsti dalla legge di bilancio. L'intervento punta a favorire l'aggiornamento strutturale per i collegamenti internazionali. Lo riferisce Financial Times.",
   "more": [
    "Gli investimenti nelle infrastrutture di trasporto urbano e ferroviario rappresentano un pilastro fondamentale per lo sviluppo economico delle grandi metropoli europee, migliorando la mobilità dei pendolari e l'interconnessione con le reti di trasporto a lunga percorrenza."
   ],
