   "id": "z8a206e47",
   "sez": "economia",
   "titolo": "I costi totali del Centro Presidenziale Obama raggiungono un miliardo di dollari",
   "orig": "Obama Presidential Center Reaches $1B in Total Costs",
   "lead": "La Fondazione Obama ha annunciato che il costo complessivo del campus presidenziale ha toccato quota un miliardo di dollari. L'aumento della spesa è stato guidato dall'ampliamento del progetto originario, dall'inclusione di opere d'arte pubbliche e dai costi assicurativi, mentre alcuni subappaltatori lamentano il mancato pagamento dei compensi a causa di contenziosi legali ancora irrisolti. Lo riferisce Engineering News-Record.",
   "more": [
    "La realizzazione di grandi complessi museali e istituzionali dedicati agli ex capi di Stato comporta spesso complesse pianificazioni finanziarie, soggette a variazioni di budget dovute all'espansione delle opere architettoniche e alle dinamiche contrattuali con le imprese edili."
   ],
