   "sez": "spazio",
   "titolo": "Una rara tempesta di radiazione solare offre agli scienziati un quadro più chiaro dei rischi per i voli",
   "orig": "Rare solar radiation storm gives scientists clearest picture yet of flight risks",
   "lead": "Una nuova ricerca guidata dall'Università di Surrey ha analizzato il set di dati più completo mai raccolto nell'atmosfera terrestre durante un evento di radiazione solare. Lo studio evidenzia l'importanza di un monitoraggio della radiazione spaziale meglio coordinato al fine di garantire la sicurezza della navigazione aerea civile. Lo riferisce Phys.org – Spazio.",
   "more": [
    "Le tempeste di radiazione solare emettono flussi di particelle energetiche che, raggiungendo gli strati superiori dell'atmosfera terrestre, possono interferire con i sistemi di comunicazione e la strumentazione di bordo dei velivoli che volano sulle rotte polari o ad alta quota."
   ],
