   "id": "z0813af16",
   "sez": "salute",
   "titolo": "Risultati clinici favorevoli a lungo termine con la strategia 'treat-to-target' nell'artrite reumatoide precoce",
   "orig": "Favorable long-term outcomes seen with treat-to-target strategy in early rheumatoid arthritis",
   "lead": "Uno studio pubblicato online sugli Annals of the Rheumatic Diseases mostra che i pazienti affetti da artrite reumatoide precoce gestiti mediante una strategia terapeutica basata sul raggiungimento di obiettivi specifici ('treat-to-target') ottengono tassi di remissione sostenuta più elevati e una migliore funzionalità fisica a distanza di dieci anni. Lo riferisce Medical Xpress.",
   "more": [
    "L'artrite reumatoide è una malattia infiammatoria cronica autoimmune che colpisce le articolazioni. Un intervento farmacologico precoce e mirato a bloccare l'attività della malattia è considerato fondamentale per prevenire danni articolari irreversibili nel lungo periodo."
   ],
