   "id": "z2abd08ae",
   "sez": "prima",
   "titolo": "Confermati casi di Ebola ad Abuja: l'epidemia si estende alla Nigeria",
   "orig": "Nigeria confirms an Ebola case in Abuja as a woman arriving from Uganda tests positive",
   "lead": "Il ministero della Salute nigeriano ha confermato il primo caso di Ebola nella capitale Abuja, rilevato in una donna proveniente dall'Uganda che ha manifestato i primi sintomi il 7 ottobre scorso. Le autorità hanno già identificato 44 contatti stretti per avviare il tracciamento preventivo. La Nigeria diventa così l'ultimo Paese africano colpito da una diffusione regionale che ha già toccato il Kenya, dove si registrano nove infezioni dall'inizio del mese. La notizia aggrava il quadro sanitario dell'area, sollevando timori per la rapidità del contagio internazionale nonostante le smentite di alcuni governi vicini.",
   "more": [
    "L'Ebola è un virus altamente contagioso che provoca febbri emorragiche spesso letali. Si trasmette attraverso il contatto con fluidi corporei di persone o animali infetti. Il contenimento richiede misure rigorose di isolamento e il tracciamento dei contatti. Abuja, centro amministrativo e politico della Nigeria, rappresenta uno snodo cruciale per la popolosa nazione africana, rendendo la gestione del focolaio una priorità per la sicurezza sanitaria internazionale."
   ],
