   "id": "z5dcb3883",
   "sez": "prima",
   "titolo": "Alberta rifiuta l'indipendenza: vittoria decisiva per l'unità del Canada",
   "orig": "Alberta's decisive decision to stay in Canada gives Carney backing to take on Trump",
   "lead": "Gli elettori dell'Alberta hanno respinto con una maggioranza schiacciante la proposta di avviare un percorso di indipendenza dal Canada. Il referendum non vincolante ha visto circa tre quarti dei votanti opporsi alla separazione, consegnando una vittoria politica fondamentale al primo ministro Mark Carney. L'esito della consultazione rafforza la posizione di Carney nel promuovere piani economici nazionali e progetti infrastrutturali, come i nuovi oleodotti, in un momento di forti tensioni commerciali con gli Stati Uniti. La decisione segna un punto di svolta per il movimento separatista della provincia petrolifera.",
   "more": [
    "L'Alberta è la principale provincia produttrice di petrolio del Canada e ha storicamente mantenuto un rapporto complesso con il governo federale di Ottawa, lamentando spesso disparità nel trattamento economico. Il referendum rappresenta uno strumento di democrazia diretta che, sebbene non vincolante legalmente, esercita una profonda pressione politica, definendo il futuro delle relazioni costituzionali e la stabilità dei mercati energetici nordamericani."
   ],
