   "id": "zd6e871d8",
   "sez": "prima",
   "titolo": "Tariffe canadesi: azione legale negli Stati Uniti contro le decisioni di Trump",
   "orig": "Trump sued over Canadian tariffs in latest legal challenge",
   "lead": "Un gruppo di importatori e organizzazioni non-profit statunitensi, tra cui il Liberty Justice Center e Gellert Global Group, ha intentato una causa presso la Corte di Commercio Internazionale degli Stati Uniti contro le tariffe imposte dal presidente Donald Trump sui beni canadesi. I legali sostengono che la Casa Bianca abbia ecceduto la propria autorità, bypassando il Congresso e utilizzando in modo improprio leggi dell'era della Grande Depressione. L'azione legale sottolinea come i dazi del 50% stiano causando danni economici immediati alle imprese americane e ai consumatori locali.",
   "more": [
    "Le tariffe sono imposte sulle importazioni estere per proteggere le industrie nazionali, ma spesso aumentano i costi per gli importatori e i prezzi per i consumatori finali. La Corte di Commercio Internazionale è l'organo giudiziario specializzato che negli Stati Uniti decide sulla legittimità delle azioni esecutive in materia doganale, bilanciando il potere presidenziale con le normative stabilite dal potere legislativo del Congresso."
   ],
