   "id": "z38110afb",
   "sez": "prima",
   "titolo": "Sicurezza, via libera al nuovo decreto: stretta sui minori e 500 militari a Milano",
   "orig": "Meloni: fermo preventivo per i minori",
   "lead": "Il Consiglio dei Ministri ha approvato un nuovo decreto sicurezza che introduce misure rigorose, tra cui l'estensione del fermo preventivo per i minori nei luoghi affollati e l'immediata imputabilità degli stessi. Tra le novità principali figura il reato di \"partecipazione violenta a manifestazioni\" e l'invio di 500 militari a Milano per il rafforzamento dell'ordine pubblico, pur senza funzioni di polizia giudiziaria. La Premier Meloni ha difeso il provvedimento definendo inaccettabili le recenti violenze, mentre dal Quirinale emergono perplessità riguardo all'attribuzione di poteri speciali alle forze armate.",
   "more": [
    "Un decreto sicurezza è un atto normativo d'urgenza con forza di legge emanato dal Governo per affrontare situazioni di ordine pubblico. Deve essere convertito in legge dal Parlamento entro sessanta giorni. L'impiego dei militari in contesti urbani, noto in Italia come operazione \"Strade Sicure\", è una pratica consolidata per presidiare obiettivi sensibili, ma la concessione di poteri di identificazione resta oggetto di dibattito giuridico."
   ],
