   "id": "zcf455e2a",
   "sez": "sport",
   "titolo": "Calcio sudamericano: Boca Juniors in finale, Internacional in semifinale femminile",
   "orig": "Inter e Bragantino avançam às semifinais da Copa do Brasil Feminina",
   "lead": "Il Boca Juniors ha raggiunto la finale della Copa Sudamericana grazie a una vittoria per 3-1 contro il Vasco da Gama al Maracanã, trascinato da un gol decisivo di Leandro Paredes nel finale. Contemporaneamente, in Brasile sono stati definiti i primi verdetti della Copa do Brasil femminile: l'Internacional ha superato l'Atlético-MG ai rigori dopo un pareggio a reti inviolate, mentre il Red Bull Bragantino ha eliminato la Ferroviária nonostante una sconfitta per 3-2, facendo valere il vantaggio ottenuto nella gara di andata.",
   "more": [
    "La Copa Sudamericana è la seconda competizione calcistica continentale per club più prestigiosa del Sud America, paragonabile all'Europa League. La Copa do Brasil femminile è il principale torneo a eliminazione diretta per le squadre femminili brasiliane. Entrambe le competizioni rappresentano momenti chiave della stagione calcistica sudamericana, attirando grande attenzione per la rivalità storica tra club argentini e brasiliani in stadi iconici come il Maracanã."
   ],
