     "n": "NPR",
     "c": "Washington",
     "p": "US",
     "t": "La testata statunitense pubblica riferisce la conferma di un caso di Ebola ad Abuja da parte del Ministero della Salute, specificando che la paziente è una donna arrivata dall'Uganda con sintomi iniziati il 7 ottobre. Riporta le dichiarazioni del ministro Muhammad Pate sulla tracciabilità di 44 contatti e cita l'allarme del direttore generale dell'Africa CDC, Jean Kaseya, sulla gravità della minaccia e sul tasso di mortalità vicino al 50%.",
