     "c": "Toronto",
     "p": "XX",
     "t": "L'emittente pubblica canadese riporta la conferma del Ministero della Salute guidato da Muhammad Ali Pate, evidenziando il ricovero in isolamento e i 44 contatti tracciati. Inserisce la replica del portavoce ugandese Alan Kasujja («There's no Ebola in Uganda») e richiama il bilancio dell'epidemia in corso nella Repubblica Democratica del Congo.",
     "b": "a"
