     "t": "La testata privata britannica, priva del testo leggibile, evidenzia nel titolo la reazione stizzita dell'Uganda a seguito della conferma del primo caso di Ebola in Nigeria. L'occhiello ribadisce l'internazionalizzazione della diffusione virale. Il giudizio su questo articolo è parziale.",
