   "divergono": "Le testate divergono sulla ricostruzione del transito della paziente infetta: The Guardian precisa, citando il ministero ugandese, che la donna è una cittadina nigeriana in viaggio d'affari nel Congo orientale che ha solo fatto transito in Uganda, mentre NPR e CBC News indicano genericamente che la donna è arrivata dall'Uganda o viaggiava da lì. Sul fronte delle reazioni, testate come Sky News e CBC News mettono in risalto la netta presa di posizione del portavoce ugandese Alan Kasujja con la frase «There's no Ebola in Uganda», un dettaglio omesso da NPR e Premium Times che si concentrano invece sulle misure interne di contenimento adottate ad Abuja."
